  'bulk_1788453066821_162_m92v', '-P0c5bn30pUNxxABJF5_', 'bulk_1788453066821_162', 'رحمة سليمان', '', 'مركز الأمـيـر للتكييف و صيانة الأجهزة المنزلية', 'mrkz-alamyr-lltkyyf-w-syana-alaghza-almnzlya-ABJF5_', 5, 'ما شاء الله تبارك الله، أمانة وإتقان وسرعة في الرد، أنصح أي حد محتاج تنظيف وغسيل التكييف يتعامل مع مركز الأمـيـر للتكييف و صيانة الأجهزة المنزلية.', 1, 0, 1779193503146, 1779193503146
);
